/* DeltaX Preflight demo renderer. No dependencies.
 * Data contract: window.PREFLIGHT_DEMO_FIXTURES (from fixtures.js, generated by the validator).
 * Every status, count, verdict and receipt is read from scene.result. Nothing is invented. */
(function () {
  'use strict';

  var ORDER = ['reviewed-proposal', 'changed-payload', 'two-valid-options', 'refused-publication'];
  var SCENE_MS = 13000;            // 4 scenes x 13 s = 52 s walkthrough
  var REVEAL_MS = [0, 2800, 5600]; // proposal -> policy+evidence -> result
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // Outcome copy is keyed by result.status so it follows the real data.
  var COPY = {
    PASS_SINGLE: {
      head: 'Exactly one candidate is admissible.',
      sub: 'This is validation, not authorization or execution. Nothing runs; the check only reports which candidate satisfies the owner’s hard constraints.'
    },
    EVIDENCE_REQUIRED: {
      head: 'A candidate is unproven, so the check stops.',
      sub: 'At least one candidate lacks the evidence its checks need. Unproven is not proven malicious: the owner’s reviewed evidence simply does not cover this exact proposal. No handoff is produced.'
    },
    SELECTION_REQUIRED: {
      head: 'More than one candidate is admissible. Selection remains open.',
      sub: 'Preflight does not choose. A person narrows the proposal, or a separate, authorized selection process resolves it.'
    },
    REFUSE: {
      head: 'No candidate is admissible.',
      sub: 'Every proposed candidate fails a hard constraint and none is unproven. Nothing runs.'
    }
  };
  var VERDICT = {
    admissible: { mark: '✓', cls: 'v-admissible', label: 'admissible' },
    rejected:   { mark: '✕', cls: 'v-rejected',   label: 'rejected' },
    unproven:   { mark: '?', cls: 'v-unproven',   label: 'unproven' }
  };

  // ---------- helpers ----------
  function h(tag, attrs, kids) {
    var el = document.createElement(tag);
    if (attrs) for (var k in attrs) {
      if (attrs[k] == null) continue;
      if (k === 'class') el.className = attrs[k];
      else if (k === 'text') el.textContent = attrs[k];
      else el.setAttribute(k, attrs[k]);
    }
    (kids || []).forEach(function (c) {
      if (c == null || c === false) return;
      el.appendChild(typeof c === 'string' ? document.createTextNode(c) : c);
    });
    return el;
  }
  function $(id) { return document.getElementById(id); }
  function isObj(x) { return x !== null && typeof x === 'object' && !Array.isArray(x); }
  function arr(x) { return Array.isArray(x) ? x : []; }
  function fmt(v) { return typeof v === 'string' ? JSON.stringify(v) : JSON.stringify(v); }
  function same(a, b) { return JSON.stringify(canon(a)) === JSON.stringify(canon(b)); }
  function canon(x) {
    if (Array.isArray(x)) return x.map(canon);
    if (isObj(x)) { var o = {}; Object.keys(x).sort().forEach(function (k) { o[k] = canon(x[k]); }); return o; }
    return x;
  }
  function byId(list, id) { return arr(list).filter(function (c) { return c && c.id === id; })[0]; }
  function hasFacts(ev, id) { var c = byId(ev && ev.candidates, id); return !!(c && isObj(c.facts) && Object.keys(c.facts).length); }

  // ---------- load + validate ----------
  var F = window.PREFLIGHT_DEMO_FIXTURES;
  var valid = isObj(F) && Array.isArray(F.scenes) && F.scenes.length > 0 &&
    F.scenes.every(function (s) { return isObj(s) && typeof s.id === 'string'; });

  renderProvenance(valid ? F : null);

  if (!valid) {
    $('fixtures-missing').hidden = false;
    $('tabs').closest('.controls').hidden = true;
    var st = $('stage');
    st.removeAttribute('role'); st.removeAttribute('aria-labelledby');
    st.innerHTML = '';
    st.appendChild(h('p', { class: 'empty-stage', text: 'Fixtures unavailable. Place fixtures.js (generated by the validator) next to index.html and reload.' }));
    return;
  }

  var scenes = F.scenes.slice().sort(function (a, b) {
    var ia = ORDER.indexOf(a.id), ib = ORDER.indexOf(b.id);
    return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
  });

  // Reviewed payloads: a candidate payload from any scene whose reviewed evidence carried facts for it.
  var reviewed = {};
  scenes.forEach(function (s) {
    arr(s.decision && s.decision.candidates).forEach(function (c) {
      if (c && c.id && isObj(c.payload) && hasFacts(s.evidence, c.id) && !reviewed[c.id])
        reviewed[c.id] = { payload: c.payload, from: s };
    });
  });

  // ---------- tabs ----------
  var tabsEl = $('tabs'), tabs = [];
  scenes.forEach(function (s, i) {
    var status = s.result && typeof s.result.status === 'string' ? s.result.status : '—';
    var t = h('button', {
      type: 'button', role: 'tab', class: 'tab', id: 'tab-' + s.id,
      'aria-controls': 'stage', 'aria-selected': 'false', tabindex: '-1'
    }, [
      h('span', { class: 'n', text: 'Scene ' + (i + 1) }),
      h('span', { class: 't', text: s.title || s.id }),
      h('span', { class: 's st-text-' + status, text: status })
    ]);
    t.addEventListener('click', function () { stop(); show(i, true); });
    t.addEventListener('keydown', function (e) {
      var n = scenes.length, j = null;
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') j = (i + 1) % n;
      else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') j = (i - 1 + n) % n;
      else if (e.key === 'Home') j = 0;
      else if (e.key === 'End') j = n - 1;
      if (j !== null) { e.preventDefault(); stop(); show(j, true); tabs[j].focus(); }
    });
    tabs.push(t); tabsEl.appendChild(t);
  });

  var segs = scenes.map(function () { var i = h('i'); $('progress').appendChild(h('div', { class: 'seg' }, [i])); return i; });

  // ---------- scene render ----------
  var current = 0;
  function show(i, announce) {
    current = i;
    var s = scenes[i];
    tabs.forEach(function (t, k) {
      t.setAttribute('aria-selected', k === i ? 'true' : 'false');
      t.tabIndex = k === i ? 0 : -1;
    });
    $('stage').setAttribute('aria-labelledby', 'tab-' + s.id);
    $('scene-kicker').textContent = 'Scene ' + (i + 1) + ' of ' + scenes.length + ' · ' + s.id;
    $('scene-title').textContent = s.title || s.id;
    $('scene-desc').textContent = s.description || '';
    fill('col-proposal', renderProposal(s));
    fill('col-policy', renderPolicy(s));
    fill('col-result', renderResult(s));
    fill('raw', renderRaw(s));
    segs.forEach(function (seg, k) { seg.style.width = k < i ? '100%' : '0%'; });
    if (announce) {
      var st = s.result && s.result.status;
      $('live').textContent = 'Scene ' + (i + 1) + ': ' + (s.title || s.id) + '. Result ' + (st || 'not present in fixture') + '. ' + (COPY[st] ? COPY[st].head : '');
    }
    try { history.replaceState(null, '', '#' + s.id); } catch (e) {}
  }
  function fill(id, node) { var el = $(id); el.innerHTML = ''; el.appendChild(node); }

  function kvList(obj, hlKeys) {
    return h('ul', { class: 'kv' }, Object.keys(obj).map(function (k) {
      var changed = hlKeys && hlKeys.indexOf(k) >= 0;
      return h('li', null, [h('span', { class: 'k', text: k + ':' }), h('span', { class: changed ? 'v hl' : 'v', text: fmt(obj[k]) })]);
    }));
  }

  function renderProposal(s) {
    var d = s.decision, frag = document.createDocumentFragment();
    if (!isObj(d)) { frag.appendChild(h('p', { class: 'unknown-shape', text: 'No decision object in fixture.' })); return frag; }
    frag.appendChild(h('p', { class: 'meta' }, ['decision_id ', h('code', { text: String(d.decision_id) })]));
    var diffs = [];
    arr(d.candidates).forEach(function (c) {
      var rv = reviewed[c.id], changedKeys = [];
      if (rv && isObj(c.payload) && !same(rv.payload, c.payload)) {
        var keys = Object.keys(rv.payload).concat(Object.keys(c.payload));
        keys.forEach(function (k) { if (changedKeys.indexOf(k) < 0 && !same(rv.payload[k], c.payload[k])) changedKeys.push(k); });
        diffs.push({ c: c, rv: rv, keys: changedKeys });
      }
      var tag = changedKeys.length ? h('span', { class: 'tag amber', text: 'same ID · payload changed' })
        : (rv && same(rv.payload, c.payload) ? h('span', { class: 'tag silver', text: 'matches reviewed' }) : null);
      frag.appendChild(h('div', { class: 'cand' + (changedKeys.length ? ' changed' : '') }, [
        h('div', { class: 'cand-id' }, [h('span', { text: c.id }), tag]),
        isObj(c.payload) ? kvList(c.payload, changedKeys) : null
      ]));
    });
    diffs.forEach(function (x) {
      var box = h('div', { class: 'diff', role: 'group', 'aria-label': 'Payload change for ' + x.c.id }, [
        h('div', { class: 'diff-h', text: 'Payload drift · id "' + x.c.id + '" unchanged' })
      ]);
      x.keys.forEach(function (k) {
        box.appendChild(h('div', { class: 'diff-row del' }, [h('span', { class: 'lab', text: 'Reviewed' }), h('span', { class: 'val', text: k + ': ' + fmt(x.rv.payload[k]) })]));
        box.appendChild(h('div', { class: 'diff-row add' }, [h('span', { class: 'lab', text: 'Proposed' }), h('span', { class: 'val', text: k + ': ' + fmt(x.c.payload[k]) })]));
      });
      box.appendChild(h('div', { class: 'diff-src', text: 'Reviewed payload taken from scene “' + (x.rv.from.title || x.rv.from.id) + '”, where the owner’s evidence covered it.' }));
      frag.appendChild(box);
    });
    return frag;
  }

  function renderPolicy(s) {
    var p = s.policy, e = s.evidence, frag = document.createDocumentFragment();
    if (isObj(p)) {
      frag.appendChild(h('p', { class: 'meta' }, ['policy_id ', h('code', { text: String(p.policy_id) })]));
      arr(p.constraints).forEach(function (c) {
        frag.appendChild(h('div', { class: 'rule' }, [
          h('span', { class: 'rid', text: c.id }),
          h('span', { class: 'rexpr', text: (c.source ? c.source + ' ' : '') + c.path + ' ' + c.op + (c.op === 'exists' ? '' : ' ' + fmt(c.value)) })
        ]));
      });
    } else frag.appendChild(h('p', { class: 'unknown-shape', text: 'No policy object in fixture.' }));

    frag.appendChild(h('p', { class: 'sub', text: 'Reviewed evidence' }));
    if (isObj(e)) {
      frag.appendChild(h('p', { class: 'meta' }, ['source ', h('code', { text: String(e.source) })]));
      arr(e.candidates).forEach(function (c) {
        var empty = !isObj(c.facts) || !Object.keys(c.facts).length;
        frag.appendChild(h('div', { class: 'cand' + (empty ? ' changed' : '') }, [
          h('div', { class: 'cand-id' }, [h('span', { text: c.id }), empty ? h('span', { class: 'tag amber', text: 'no reviewed match' }) : null]),
          empty ? h('p', { class: 'facts-empty', text: 'facts: {} — the owner’s manifest has no entry for this exact payload' }) : kvList(c.facts)
        ]));
      });
    } else frag.appendChild(h('p', { class: 'unknown-shape', text: 'No evidence object in fixture.' }));
    return frag;
  }

  function renderResult(s) {
    var r = s.result, frag = document.createDocumentFragment();
    if (!isObj(r)) { frag.appendChild(h('p', { class: 'unknown-shape', text: 'No result object in fixture.' })); return frag; }
    var st = typeof r.status === 'string' ? r.status : null;
    frag.appendChild(h('p', { class: 'status ' + (COPY[st] ? 'st-' + st : 'st-unknown'), text: st || 'status not present' }));
    if (COPY[st]) {
      frag.appendChild(h('p', { class: 'explain', text: COPY[st].head }));
      frag.appendChild(h('p', { class: 'explain-sub', text: COPY[st].sub }));
    } else if (st) {
      frag.appendChild(h('p', { class: 'explain-sub', text: 'Unrecognized status; see the raw result below.' }));
    }
    if (isObj(r.counts)) {
      frag.appendChild(h('ul', { class: 'counts', 'aria-label': 'Counts' }, Object.keys(r.counts).map(function (k) {
        return h('li', null, [k + ' ', h('b', { text: String(r.counts[k]) })]);
      })));
    }
    if (Array.isArray(r.admissible_candidate_ids)) {
      frag.appendChild(h('p', { class: 'ids' }, ['admissible_candidate_ids ', h('b', { text: JSON.stringify(r.admissible_candidate_ids) })]));
    }
    arr(r.candidates).forEach(function (c) {
      var v = VERDICT[c.verdict] || { mark: '•', cls: 'v-other', label: String(c.verdict) };
      frag.appendChild(h('div', { class: 'verdict' }, [
        h('span', { class: 'mark ' + v.cls, 'aria-hidden': 'true', text: v.mark }),
        h('span', { class: 'vname' }, [String(c.id), h('span', { class: 'vw ' + v.cls, text: v.label })]),
        h('ul', { class: 'checks' }, arr(c.checks).map(function (k) {
          return h('li', null, [k.constraint_id + ': ', h('span', { class: 'o-' + k.outcome, text: String(k.outcome) }), k.reason ? ' (' + k.reason + ')' : '']);
        }))
      ]));
    });
    if (isObj(r.receipt)) {
      var dl = h('dl');
      Object.keys(r.receipt).forEach(function (k) {
        var val = r.receipt[k];
        dl.appendChild(h('dt', { text: k }));
        dl.appendChild(h('dd', { text: typeof val === 'string' ? val : JSON.stringify(val) }));
      });
      var short = '';
      var rh = r.receipt.result_hash;
      if (typeof rh === 'string' && rh.length) short = (r.receipt.algorithm ? r.receipt.algorithm + ':' : '') + rh.slice(0, 12) + (rh.length > 12 ? '…' : '');
      frag.appendChild(h('details', { class: 'receipt' }, [
        h('summary', null, [h('span', { class: 'rh', text: 'Receipt' }), short ? h('span', { class: 'rshort', text: ' ' + short }) : null]),
        dl
      ]));
    }
    return frag;
  }

  function renderRaw(s) {
    var frag = document.createDocumentFragment();
    ['decision', 'policy', 'evidence', 'result'].forEach(function (k) {
      if (s[k] === undefined) return;
      frag.appendChild(h('h4', { text: k }));
      frag.appendChild(h('pre', { tabindex: '0', 'aria-label': k + ' JSON', text: JSON.stringify(s[k], null, 2) }));
    });
    return frag;
  }

  // ---------- walkthrough player ----------
  var playing = false, startAt = 0, elapsed = 0, raf = 0, revealed = -1;
  var playBtn = $('play'), flow = $('flow');
  function setReveal(n) {
    if (n === revealed) return; revealed = n;
    var cols = flow.querySelectorAll('.col');
    for (var i = 0; i < cols.length; i++) cols[i].classList.toggle('on', i < n);
  }
  function tick(now) {
    if (!playing) return;
    var t = elapsed + (now - startAt);
    if (t >= SCENE_MS) {
      segs[current].style.width = '100%';
      if (current >= scenes.length - 1) { stop(true); return; }
      elapsed = 0; startAt = now; revealed = -1;
      show(current + 1, true); t = 0;
    }
    segs[current].style.width = (100 * t / SCENE_MS) + '%';
    var n = 0; REVEAL_MS.forEach(function (ms) { if (t >= ms) n++; });
    if (!reduce) setReveal(n); else setReveal(3);
    raf = requestAnimationFrame(tick);
  }
  function play() {
    if (playing) return;
    playing = true;
    if (!reduce) flow.classList.add('staged');
    startAt = performance.now(); revealed = -1;
    playBtn.setAttribute('aria-pressed', 'true');
    playBtn.querySelector('.btn-icon').textContent = '❚❚';
    playBtn.querySelector('.btn-label').textContent = 'Pause walkthrough';
    $('live').textContent = 'Walkthrough playing. Scene ' + (current + 1) + ': ' + (scenes[current].title || scenes[current].id) + '.';
    raf = requestAnimationFrame(tick);
  }
  function pause() {
    if (!playing) return;
    playing = false; cancelAnimationFrame(raf);
    elapsed += performance.now() - startAt;
    flow.classList.remove('staged'); setReveal(3);
    setPaused('Resume walkthrough');
    $('live').textContent = 'Walkthrough paused.';
  }
  function stop(finished) {
    playing = false; cancelAnimationFrame(raf); elapsed = 0;
    flow.classList.remove('staged'); setReveal(3);
    setPaused(finished ? 'Replay walkthrough' : 'Play walkthrough');
    if (finished) { $('live').textContent = 'Walkthrough finished.'; restartNext = true; }
    else restartNext = false;
  }
  var restartNext = false;
  function setPaused(label) {
    playBtn.setAttribute('aria-pressed', 'false');
    playBtn.querySelector('.btn-icon').textContent = '▶';
    playBtn.querySelector('.btn-label').textContent = label;
  }
  function toggle() {
    if (playing) return pause();
    if (restartNext) { restartNext = false; show(0, true); }
    play();
  }
  playBtn.addEventListener('click', toggle);
  var NATIVE = 'a, button, input, textarea, select, summary, details, pre, .raw, [contenteditable], [role="tab"], [tabindex]:not(#stage)';
  document.addEventListener('keydown', function (e) {
    if (e.defaultPrevented || e.altKey || e.ctrlKey || e.metaKey) return;
    var tgt = e.target;
    if (tgt && tgt.closest && tgt.closest(NATIVE)) return;   // let native activation / scrolling work
    if (e.key === ' ' || e.key === 'Enter' || e.key === 'k') { e.preventDefault(); toggle(); }
  });

  // ---------- initial state ----------
  var start = 0, hash = (location.hash || '').slice(1);
  scenes.forEach(function (s, i) { if (s.id === hash) start = i; });
  show(start, false);
  setReveal(3);
  if (!reduce && /[?&]autoplay=1/.test(location.search)) play();

  function renderProvenance(f) {
    var dl = $('provenance'); if (!dl) return;
    dl.innerHTML = '';
    if (!f) { dl.appendChild(h('dt', { text: 'fixtures' })); dl.appendChild(h('dd', { text: 'not loaded' })); return; }
    var src = isObj(f.source) ? f.source : {};
    ['validator', 'evidence_producer', 'decision', 'policy', 'manifest'].forEach(function (k) {
      if (src[k] === undefined) return;
      dl.appendChild(h('dt', { text: k })); dl.appendChild(h('dd', { text: String(src[k]) }));
    });
    dl.appendChild(h('dt', { text: 'schema_version' })); dl.appendChild(h('dd', { text: String(f.schema_version) }));
  }
})();
